    if (clear) svg.appendChild(el("text", {x: margin.left + 10, y: Y(rf[0]) - 10, "text-anchor": "start", "font-size": 7, "font-weight": 700, fill: rf[1], "font-family": FF}, rf[2]));
  });
  svg.appendChild(el("text", {x: XP(evI) + 3, y: MT + 20, "text-anchor": "start", "font-size": 7, "font-weight": 700, fill: "#1a3560", "font-family": FF}, "GUERRE EN IRAN"));
  var dh = head[n-1] - head[t0], dt = trim[tn-1] - trim[0];
  svg.appendChild(el("text", {x: margin.left + 8, y: MT + 12, "text-anchor": "start", "font-size": 8, fill: "#444444", "font-family": FF}, "DEPUIS JANVIER : GLOBAL " + sg(dh, 1) + " PT,"));
  svg.appendChild(el("text", {x: margin.left + 8, y: MT + 22, "text-anchor": "start", "font-size": 8, fill: "#444444", "font-family": FF}, "TRONQ. " + sg(dt, 1) + " PT"));
